-- Run with the handoff migration in BEGIN ... ROLLBACK on TEST only.
SET LOCAL ROLE service_role;
DO $$
DECLARE r uuid;a uuid;b uuid;d uuid;c uuid;cd uuid;ia uuid;ib uuid;idline uuid;v integer;fv integer;target text;before_a jsonb;before_b jsonb;before_d jsonb;blocked boolean;final_version integer;actor text:='normal-reception-fixture@example.invalid';
BEGIN
 SELECT value INTO target FROM public.refurb_status_options WHERE lower(trim(label))='rma to fix';
 IF target IS NULL THEN RAISE EXCEPTION 'Existing RMA to fix is required'; END IF;
 INSERT INTO public.refurb_receptions(reception_number,reception_date,supplier,vat_scheme,supplier_invoice_nr) VALUES('TEST-NORMAL-RMA-'||gen_random_uuid(),current_date,'TEST NORMAL RMA','margin','TEST ONLY') RETURNING id INTO r;
 INSERT INTO public.refurb_reception_items(reception_id,row_index,refurb_status,sku,used_parts,price_cents,compensation_cents,rma_registered) VALUES(r,0,'RMA','TEST-A','-',10000,10000,true) RETURNING id INTO a;
 INSERT INTO public.refurb_reception_items(reception_id,row_index,refurb_status,sku,used_parts,price_cents,compensation_cents,rma_registered) VALUES(r,1,'RMA','TEST-B','-',9000,9000,true) RETURNING id INTO b;
 INSERT INTO public.refurb_reception_items(reception_id,row_index,refurb_status,sku,used_parts,price_cents,compensation_cents,rma_registered) VALUES(r,2,'booked','TEST-OLD-BOOKED','-',20000,20000,true) RETURNING id INTO d;
 SELECT to_jsonb(s) INTO before_a FROM public.refurb_reception_items s WHERE id=a;
 SELECT to_jsonb(s) INTO before_b FROM public.refurb_reception_items s WHERE id=b;
 SELECT to_jsonb(s) INTO before_d FROM public.refurb_reception_items s WHERE id=d;
 c:=public.assign_reception_supplier_rma(r,array[a,b],NULL,false,false,actor);
 cd:=public.assign_reception_supplier_rma(r,array[d],NULL,true,false,actor);
 SELECT id INTO ia FROM public.supplier_rma_items WHERE case_id=c AND reception_item_id=a;
 SELECT id INTO ib FROM public.supplier_rma_items WHERE case_id=c AND reception_item_id=b;
 SELECT id INTO idline FROM public.supplier_rma_items WHERE case_id=cd;
 SELECT version INTO v FROM public.supplier_rma_cases WHERE id=c;
 PERFORM public.resolve_supplier_rma('decision',jsonb_build_object('case_id',c,'item_id',ia,'version',v,'decision','approved'),actor);
 PERFORM public.resolve_supplier_rma('custody',jsonb_build_object('case_id',c,'item_id',ia,'followup_version',0,'custody','on_site'),actor);
 SELECT version INTO v FROM public.supplier_rma_cases WHERE id=c;
 PERFORM public.resolve_supplier_rma('decision',jsonb_build_object('case_id',c,'item_id',ib,'version',v,'decision','rejected','reason','TEST refusal'),actor);
 IF (SELECT refurb_status FROM public.refurb_reception_items WHERE id=b)<>'RMA' THEN RAISE EXCEPTION 'Reopened before physical confirmation';END IF;
 PERFORM public.resolve_supplier_rma('custody',jsonb_build_object('case_id',c,'item_id',ib,'followup_version',0,'custody','on_site'),actor);
 IF (SELECT refurb_status FROM public.refurb_reception_items WHERE id=b)<>target THEN RAISE EXCEPTION 'No actual RMA to fix status';END IF;
 IF (SELECT to_jsonb(s) FROM public.refurb_reception_items s WHERE id=a) IS DISTINCT FROM before_a THEN RAISE EXCEPTION 'Approved article changed';END IF;
 IF (SELECT original_item FROM public.supplier_rma_reception_handoffs WHERE case_item_id=ib) IS DISTINCT FROM before_b THEN RAISE EXCEPTION 'Original history missing';END IF;
 UPDATE public.refurb_reception_items SET sku='TEST-NEW-SKU',used_parts='TEST-PART-1, TEST-PART-2' WHERE id=b;
 UPDATE public.refurb_reception_items SET refurb_status=(SELECT value FROM public.refurb_status_options WHERE label='Waiting For SKU') WHERE id=b;
 UPDATE public.refurb_reception_items SET refurb_status=(SELECT value FROM public.refurb_status_options WHERE label='Finished') WHERE id=b;
 IF NOT EXISTS(SELECT 1 FROM public.supplier_rma_followups WHERE case_item_id=ib AND repair_state='repaired' AND completed_at IS NOT NULL AND repair_parts='TEST-PART-1, TEST-PART-2') THEN RAISE EXCEPTION 'Normal processing not synchronized';END IF;
 IF public.handoff_supplier_rma_to_reception(c,ib,actor) THEN RAISE EXCEPTION 'Completed article reset';END IF;
 IF (SELECT expected_cents FROM public.supplier_rma_items WHERE id=ib)<>9000 OR (SELECT decision FROM public.supplier_rma_items WHERE id=ib)<>'rejected' THEN RAISE EXCEPTION 'Claim or refusal lost';END IF;
 SELECT version INTO fv FROM public.supplier_rma_followups WHERE case_item_id=ib;
 blocked:=false;BEGIN PERFORM public.resolve_supplier_rma('repair',jsonb_build_object('case_id',c,'item_id',ib,'followup_version',fv,'repair_state','working'),actor);EXCEPTION WHEN OTHERS THEN IF SQLERRM='RMA_USE_RECEPTION' THEN blocked:=true;ELSE RAISE;END IF;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Parallel repair form accepted after handoff';END IF;
 -- Booked is still locked until refusal AND a confirmed actual return. Financial closure is independent.
 blocked:=false;BEGIN UPDATE public.refurb_reception_items SET sku='ILLEGAL' WHERE id=d;EXCEPTION WHEN OTHERS THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Ordinary booked lock bypassed';END IF;
 SELECT version INTO v FROM public.supplier_rma_cases WHERE id=cd;
 PERFORM public.resolve_supplier_rma('decision',jsonb_build_object('case_id',cd,'item_id',idline,'version',v,'decision','rejected','reason','TEST after shipping'),actor);
 PERFORM public.resolve_supplier_rma('custody',jsonb_build_object('case_id',cd,'item_id',idline,'followup_version',0,'custody','returning','outbound_on',current_date-2),actor);
 IF (SELECT to_jsonb(s) FROM public.refurb_reception_items s WHERE id=d) IS DISTINCT FROM before_d THEN RAISE EXCEPTION 'Booked article changed before return';END IF;
 SELECT version INTO v FROM public.supplier_rma_cases WHERE id=cd;
 PERFORM public.manage_supplier_rma('update_case',jsonb_build_object('case_id',cd,'version',v,'stage','rejected','supplier_reference','TEST-REFUSAL'),actor);
 SELECT version INTO v FROM public.supplier_rma_cases WHERE id=cd;
 PERFORM public.settle_supplier_rma('finalize',jsonb_build_object('case_id',cd,'version',v,'confirmed',true),actor);
 SELECT version INTO final_version FROM public.supplier_rma_cases WHERE id=cd;
 SELECT version INTO fv FROM public.supplier_rma_followups WHERE case_item_id=idline;
 PERFORM public.resolve_supplier_rma('custody',jsonb_build_object('case_id',cd,'item_id',idline,'followup_version',fv,'custody','returned','outbound_on',current_date-2,'returned_on',current_date),actor);
 IF (SELECT refurb_status FROM public.refurb_reception_items WHERE id=d)<>target THEN RAISE EXCEPTION 'Booked article not reopened after return';END IF;
 IF (SELECT original_item FROM public.supplier_rma_reception_handoffs WHERE case_item_id=idline) IS DISTINCT FROM before_d THEN RAISE EXCEPTION 'Booked history lost';END IF;
 UPDATE public.refurb_reception_items SET sku='TEST-REPAIR-SKU',used_parts='-',refurb_status=(SELECT value FROM public.refurb_status_options WHERE label='Finished') WHERE id=d;
 IF (SELECT version FROM public.supplier_rma_cases WHERE id=cd)<>final_version THEN RAISE EXCEPTION 'Financial closure changed';END IF;
 IF (SELECT count(*) FROM public.refurb_reception_items WHERE reception_id=r)<>3 THEN RAISE EXCEPTION 'Duplicate device or purchase created';END IF;
 blocked:=false;BEGIN UPDATE public.supplier_rma_reception_handoffs SET actor='ILLEGAL' WHERE case_item_id=ib;EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'Snapshot history editable';END IF;
 IF has_function_privilege('anon','public.handoff_supplier_rma_to_reception(uuid,uuid,text)','execute') OR has_table_privilege('authenticated','public.supplier_rma_reception_handoffs','select') THEN RAISE EXCEPTION 'Handoff exposed';END IF;
END $$;
SELECT 'ordinary reception processing, mixed decisions, return gating, booked history, no duplicate purchase and protected snapshot verified' AS result;
